@contextmanager
def transaction(log):
    log.append("begin")
    try:
        yield
    except ValueError:
        log.append("rollback")
        return

log = []
try:
    with transaction(log):
        raise ValueError("плохие данные")
except ValueError:
    log.append("ошибка дошла")
print(log)

